'use client';

import type { ReactNode } from 'react';

import { Separator } from '@/components/ui/separator';
import { SidebarInset, SidebarProvider, SidebarTrigger } from '@/components/ui/sidebar';

import { AppBreadcrumbs, trailFromPathname } from './app-breadcrumbs';
import { AppSidebar } from './app-sidebar';
import type {
	AppShellChrome,
	AppShellUser,
	Crumb,
	LinkComponent,
	SidebarNavGroup,
} from './app-shell.types';

/**
 * Chrome for every signed-in page: collapsible nav rail, inset content panel,
 * a header carrying the sidebar trigger, breadcrumbs and whatever you put on the
 * right.
 *
 * Everything app-specific is a prop or a slot on purpose. The shell never reaches
 * for a router, a translator, a session or a store, which is what makes it
 * portable. Feed it `pathname` and it lights the right nav item; give it
 * `linkComponent` and it uses your router's Link.
 */
export function AppShell({
	children,
	groups,
	pathname,
	chrome,
	user,
	crumbs,
	linkComponent,
	dir = 'ltr',
	headerRight,
	commandMenu,
}: {
	children: ReactNode;
	groups: readonly SidebarNavGroup[];
	pathname: string;
	chrome: AppShellChrome;
	/** Rendered at the end of the header when no `headerRight` is given. */
	user?: AppShellUser;
	/** Supply your own trail. Omitted, it is derived from `pathname` and the nav. */
	crumbs?: readonly Crumb[];
	linkComponent?: LinkComponent;
	dir?: 'ltr' | 'rtl';
	/** Replaces the default user chip. Put a locale switcher, a trial pill, anything. */
	headerRight?: ReactNode;
	/** A command palette, mounted once outside the content panel. */
	commandMenu?: ReactNode;
}) {
	const trail = trailFromPathname(pathname, groups, crumbs);

	return (
		<SidebarProvider className="overflow-hidden bg-sidebar">
			<AppSidebar
				groups={groups}
				pathname={pathname}
				chrome={chrome}
				linkComponent={linkComponent}
				dir={dir}
			/>
			<SidebarInset className="relative min-h-0 min-w-0 overflow-hidden border border-border bg-background shadow-none md:peer-data-[variant=inset]:rounded-2xl">
				<header className="flex h-11 shrink-0 items-center gap-2 border-b px-3">
					<SidebarTrigger className="-ms-1" title="Toggle sidebar" />
					<Separator orientation="vertical" className="me-2 h-4 self-auto" />
					<AppBreadcrumbs crumbs={trail} linkComponent={linkComponent} />
					<div className="ms-auto flex shrink-0 items-center gap-2">
						{headerRight ?? (user ? <UserChip user={user} /> : null)}
					</div>
				</header>
				<div className="flex min-h-0 flex-1 flex-col gap-4 overflow-y-auto p-4">{children}</div>
			</SidebarInset>
			{commandMenu}
		</SidebarProvider>
	);
}

/** Default header chip. Swap the whole thing out with `headerRight`. */
function UserChip({ user }: { user: AppShellUser }) {
	return (
		<div className="flex items-center gap-2">
			<div className="hidden text-right leading-tight sm:block">
				<p className="text-xs font-medium">{user.name}</p>
				<p className="text-[11px] text-muted-foreground">{user.email}</p>
			</div>
			{user.avatarUrl ? (
				<img src={user.avatarUrl} alt={user.name} className="size-7 rounded-full object-cover" />
			) : (
				<span className="flex size-7 items-center justify-center rounded-full bg-secondary text-[11px] font-medium">
					{user.initials}
				</span>
			)}
		</div>
	);
}

'use client';

import {
	Sidebar,
	SidebarContent,
	SidebarGroup,
	SidebarGroupLabel,
	SidebarHeader,
	SidebarMenu,
	SidebarMenuButton,
	SidebarMenuItem,
	useSidebar,
} from '@/components/ui/sidebar';
import { cn } from '@/lib/utils';

import { activeItemKey, flattenNav, itemIsActive } from './app-shell-active';
import type { AppShellChrome, LinkComponent, SidebarNavGroup } from './app-shell.types';

/**
 * The nav rail. Knows nothing about your router: it takes the current `pathname`
 * and the component to render links with, so it works with Next, React Router,
 * TanStack Router or plain anchors.
 */
export function AppSidebar({
	groups,
	pathname,
	chrome,
	linkComponent: Link = 'a',
	dir = 'ltr',
}: {
	groups: readonly SidebarNavGroup[];
	pathname: string;
	chrome: AppShellChrome;
	linkComponent?: LinkComponent;
	dir?: 'ltr' | 'rtl';
}) {
	const { state } = useSidebar();
	const isIcon = state === 'collapsed';
	const allItems = flattenNav(groups);

	return (
		<Sidebar variant="inset" collapsible="icon" dir={dir} side={dir === 'rtl' ? 'right' : 'left'}>
			<SidebarHeader
				className={cn(
					'flex flex-row items-center',
					// Matches the nav below: SidebarGroup's p-1 plus the buttons' px-2.5.
					isIcon ? 'justify-center px-0 py-3' : 'gap-2 p-1 pt-3 pb-1',
				)}
			>
				<Link
					href={chrome.brandHref}
					className={cn('flex min-w-0 items-center', isIcon ? 'justify-center' : 'gap-2 px-2.5')}
				>
					{chrome.logo}
					{!isIcon ? (
						<span className="truncate font-semibold text-foreground">{chrome.brand}</span>
					) : null}
				</Link>
			</SidebarHeader>

			<SidebarContent className="pt-2">
				{groups.map((group) => (
					<SidebarGroup key={group.key}>
						{group.label ? (
							<SidebarGroupLabel className="h-7 px-2.5 text-[10px] font-semibold tracking-[0.06em] text-muted-foreground uppercase">
								{group.label}
							</SidebarGroupLabel>
						) : null}
						<SidebarMenu>
							{group.items.map((item) => {
								// Precedence is resolved against the whole nav, not just this
								// group, so a group that lost to a nested item lights nothing.
								const active = itemIsActive(pathname, item, allItems);
								const Icon = item.icon;
								return (
									<SidebarMenuItem key={item.key}>
										<SidebarMenuButton asChild isActive={active} tooltip={item.label}>
											<Link href={item.href} aria-current={active ? 'page' : undefined}>
												<Icon className="size-4 shrink-0" aria-hidden="true" />
												<span className="min-w-0 flex-1 truncate group-data-[collapsible=icon]:hidden">
													{item.label}
												</span>
											</Link>
										</SidebarMenuButton>
									</SidebarMenuItem>
								);
							})}
						</SidebarMenu>
						{/* Kept for callers that want to know which item won in this group. */}
						<span hidden data-active-key={activeItemKey(pathname, group.items, allItems) ?? ''} />
					</SidebarGroup>
				))}
			</SidebarContent>
		</Sidebar>
	);
}

'use client';

import { Fragment } from 'react';

import {
	Breadcrumb,
	BreadcrumbItem,
	BreadcrumbLink,
	BreadcrumbList,
	BreadcrumbPage,
	BreadcrumbSeparator,
} from '@/components/ui/breadcrumb';

import type { Crumb, LinkComponent, SidebarNavGroup } from './app-shell.types';
import { flattenNav } from './app-shell-active';

/**
 * Derives a trail from the pathname and the nav, so a caller that has nothing to
 * add gets sensible crumbs for free. Segments the nav does not name are title
 * cased, and anything that looks like an id is left alone.
 */
export function trailFromPathname(
	pathname: string,
	groups: readonly SidebarNavGroup[],
	overrides: readonly Crumb[] = [],
): Crumb[] {
	if (overrides.length > 0) return [...overrides];

	const items = flattenNav(groups);
	const segments = pathname.split('/').filter(Boolean);

	return segments.map((segment, index) => {
		const href = '/' + segments.slice(0, index + 1).join('/');
		const named = items.find((item) => item.href === href);
		const isLast = index === segments.length - 1;
		const label =
			named?.label ??
			(/^\d+$/.test(segment)
				? `#${segment}`
				: segment.replace(/-/g, ' ').replace(/^./, (c) => c.toUpperCase()));
		return isLast ? { label } : { label, href };
	});
}

export function AppBreadcrumbs({
	crumbs,
	linkComponent: Link = 'a',
}: {
	crumbs: readonly Crumb[];
	linkComponent?: LinkComponent;
}) {
	if (crumbs.length === 0) return null;

	return (
		<Breadcrumb>
			<BreadcrumbList>
				{crumbs.map((crumb, index) => (
					<Fragment key={`${crumb.label}-${index}`}>
						{index > 0 && <BreadcrumbSeparator />}
						<BreadcrumbItem>
							{crumb.href ? (
								<BreadcrumbLink asChild>
									<Link href={crumb.href}>{crumb.label}</Link>
								</BreadcrumbLink>
							) : (
								<BreadcrumbPage>{crumb.label}</BreadcrumbPage>
							)}
						</BreadcrumbItem>
					</Fragment>
				))}
			</BreadcrumbList>
		</Breadcrumb>
	);
}

import type { SidebarNavItem } from './app-shell.types';

function itemMatches(pathname: string, item: SidebarNavItem) {
	if (item.activePrefix) {
		return pathname === item.href || pathname.startsWith(`${item.activePrefix}/`);
	}
	return pathname === item.href;
}

/**
 * Longest matching href wins, so a nested item beats the parent it sits under:
 * `/data/clients` must not also light up a `/data` index item.
 */
export function itemIsActive(
	pathname: string,
	item: SidebarNavItem,
	items: readonly SidebarNavItem[],
): boolean {
	if (!itemMatches(pathname, item)) return false;
	return !items.some(
		(other) =>
			other.key !== item.key &&
			other.href.length > item.href.length &&
			itemMatches(pathname, other),
	);
}

/**
 * The key of the one item that should read as current, or null.
 *
 * `against` is the set precedence is resolved over, and defaults to `items`. The
 * sidebar passes the whole nav while searching one group, so a group whose route
 * lost to a nested item in another group correctly lights nothing.
 */
export function activeItemKey(
	pathname: string,
	items: readonly SidebarNavItem[],
	against: readonly SidebarNavItem[] = items,
): string | null {
	return items.find((item) => itemIsActive(pathname, item, against))?.key ?? null;
}

/** Flattens the groups once, for the precedence checks above. */
export function flattenNav(groups: readonly { items: readonly SidebarNavItem[] }[]) {
	return groups.flatMap((group) => group.items);
}

import type { ElementType, ReactNode } from 'react';
import type { LucideIcon } from 'lucide-react';

export type SidebarNavItem = {
	/** Identity for keys and active tracking. */
	key: string;
	label: string;
	href: string;
	icon: LucideIcon;
	/** Match nested routes too, so `/orders` stays lit on `/orders/1042`. */
	activePrefix?: string;
};

export type SidebarNavGroup = {
	key: string;
	/** Group heading. Omit for a single item that needs no header. */
	label?: string;
	items: readonly SidebarNavItem[];
};

export type Crumb = {
	label: string;
	/** Omit on the last crumb: the page you are on is not a link. */
	href?: string;
};

export type AppShellUser = {
	name: string;
	email: string;
	/** Two letters at most. Shown when there is no avatar image. */
	initials: string;
	avatarUrl?: string;
};

export type AppShellChrome = {
	/** Product name beside the mark. */
	brand: string;
	/** Where the brand links to. */
	brandHref: string;
	/** Any element. A logo, an inline svg, an emoji. */
	logo: ReactNode;
};

export type LinkComponent = ElementType<{
	href: string;
	className?: string;
	children?: ReactNode;
	'aria-current'?: 'page';
}>;
